export const getSearchWikiDocumentsUrl = (params: SearchWikiDocumentsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/v1/wiki/documents/search?${stringifiedParams}`
    : `/api/v1/wiki/documents/search`;
};

/**
 * At most 50 results, ordered by keyword rank plus best passage similarity descending, then title. Semantic matches require tsolve.wiki.search.min-similarity (default 0.55). If embedding fails, only keyword matches are returned.
 * @summary Search viewable documents by words and best passage similarity.
 */
export const searchWikiDocuments = async (
  params: SearchWikiDocumentsParams,
  options?: Parameters<typeof http>[1],
): Promise<WikiDocumentSummary[]> => {
  return http<WikiDocumentSummary[]>(getSearchWikiDocumentsUrl(params), {
    ...options,
    method: 'GET',
  });
};

